"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[55565],{14629:e=>{e.exports=JSON.parse('{"id":"2026-09-10-cloud-storage-service-guides-revamped","date":"2026-09-10","products":["Analytics"],"product":"Analytics","channel":"","changeType":"Changed","title":"Cloud Storage Service guides and API reference revamped","excerpt":"The Cloud Storage Service guides and API reference have been reorganized and expanded, adding documentation for region discovery and archived-object restoration, and reordering both the guides and the reference navigation around them.","hasArticle":true,"bodyHtml":"<p>The Cloud Storage Service guides and API reference have been reorganized and expanded, adding documentation for region discovery and archived-object restoration, and reordering both the guides and the reference navigation around them.</p>\\n<h2>What&#39;s new</h2>\\n<ul>\\n<li>A new <strong>Cloud Storage Service</strong> overview guide ties together authentication, the regional base URL, object states \u2014 including the <code>ARCHIVED</code> state used for cold storage \u2014 and links to every guide and reference group.</li>\\n<li>A new <strong>Find My Regions</strong> guide documents the region-discovery request that previously lived inline inside the bulk download guide.</li>\\n<li><strong>Restore an archived object</strong> (<code>POST /objects/{objectId}/restore</code>) is now documented in the API reference, including the <code>expirationDays</code> option (1\u201310 days, default 7) that controls how long a restored copy is kept before removal.</li>\\n<li><strong>List available regions</strong> (<code>GET /regions</code>) now has its own reference page and sidebar category.</li>\\n</ul>\\n<h2>What changed</h2>\\n<ul>\\n<li>Bucket search previously took no query parameters; it now documents <code>filter</code>, <code>pageKey</code>, <code>limit</code>, <code>sortField</code>, and <code>sortDirection</code>.</li>\\n<li>List responses, including bucket search, are now documented as a paginated page object (<code>content</code>, <code>pageKey</code>, <code>pageSize</code>, <code>lastPage</code>, <code>total</code>) rather than a bare array.</li>\\n<li>The object <code>objectState</code> enum now includes <code>ARCHIVED</code>, with a note that archived objects must be restored before they can be downloaded.</li>\\n<li>The bulk-download status and download requests are now correctly documented as <code>GET</code> (previously listed as <code>POST</code>).</li>\\n<li>Guides and the API reference navigation were reordered: the Cloud Storage Service guides now lead with the overview and region discovery before object search and bulk download; the reference sidebar groups endpoints under Regions, Objects, Buckets, Bulk Downloads, and Bulk Delete.</li>\\n</ul>\\n<p>See:</p>\\n<ul>\\n<li><a href=\\"/analytics/docs/cloud-storage-service\\">Cloud Storage Service overview</a></li>\\n<li><a href=\\"/analytics/docs/cloud-storage-service-regions\\">Find My Regions</a></li>\\n<li><a href=\\"/analytics/reference/restoreobject\\">Restore an archived object</a></li>\\n<li><a href=\\"/analytics/reference/getregions\\">List available regions</a></li>\\n</ul>\\n"}')}}]);